type Preferences = {
  theme?: string
  language?: string
  notifications?: boolean
}

async function getUserPreferences(): Promise<Preferences> {
  try {
    // `cache: 'no-store'` fetches from the remote server on every request, even
    // when the route uses no Request-time APIs. The default (`auto no cache`)
    // would be fetched just once during `next build` and prerendered.
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    return res.json()
  } catch {
    // Return mock data for build time
    return { theme: 'light', language: 'en', notifications: true }
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      <ul>
        <li>Theme: {preferences.theme}</li>
        <li>Language: {preferences.language}</li>
        <li>Notifications: {preferences.notifications ? 'On' : 'Off'}</li>
      </ul>
    </div>
  )
}

